import heapq


def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        best_tuple = None
        for subset in __import__("itertools").combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in subset))
            idset = set(ids)
            if idset & blocked or not mandatory <= idset:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ends = []
            valid = True
            for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
                while ends and ends[0] <= job["start"]:
                    heapq.heappop(ends)
                heapq.heappush(ends, job["end"])
                if len(ends) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            better_tie = (best_tuple is None or
                          (ids > best_tuple if tie == "largest" else ids < best_tuple))
            if best_value is None or value > best_value or (value == best_value and better_tie):
                best_value, best_ids, best_tuple = value, list(ids), ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _ledger():
    def rounded(n, d, mode):
        if mode == "half_up":
            return (2 * n + d) // (2 * d)
        return n // d

    def solve(data):
        winners = {}
        cutoff = data.get("cutoff", 10**9)
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            eid = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if eid not in winners or key > winners[eid][0]:
                winners[eid] = (key, event)
        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(raw * event.get("tax_bp", 0), 10000, data["rounding"])
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _dependency_solver():
    def solve(data):
        packages = data["packages"]
        names = list(packages)
        choices = []
        for name in names:
            rows = packages[name]
            choices.append([None] + [row["version"] for row in rows])
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        best = None
        best_versions = None

        for vals in product(*choices):
            selected = {name: version for name, version in zip(names, vals)
                        if version is not None}
            graph = {}
            reachable = set()
            stack = list(data["roots"])
            valid = True
            while stack and valid:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                version = selected.get(name)
                if version is None:
                    valid = False
                    break
                if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                    valid = False
                    break
                row = next((r for r in packages[name] if r["version"] == version), None)
                if row is None:
                    valid = False
                    break
                if name in data["roots"]:
                    low, high = data["roots"][name]
                    if not low <= version <= high:
                        valid = False
                        break
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    depname = dep["name"]
                    depversion = selected.get(depname)
                    if depversion is None or not dep["min"] <= depversion <= dep["max"]:
                        valid = False
                        break
                    deps.append(depname)
                    stack.append(depname)
                graph[name] = deps
            if not valid or reachable != set(selected):
                continue

            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                if any(not visit(child) for child in graph.get(name, [])):
                    return False
                state[name] = 2
                return True
            if any(not visit(name) for name in reachable):
                continue

            order = sorted(names, reverse=True)
            vector = tuple(selected.get(name, -1) for name in order)
            if best is None or vector < best:
                best = vector
                best_versions = selected
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _routes():
    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        masks = {}
        for node in range(data["n"]):
            mask = 0
            for i, required_node in enumerate(required):
                if node == required_node:
                    mask |= 1 << i
            masks[node] = mask
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        initial = (source, masks[source], data["coupons"])
        start = data["start"]
        dist = {initial: start}
        queue = [(start, source, masks[source], data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and time <= data["deadline"]:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                for duration, next_remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | masks[nxt]
                    next_state = (nxt, next_mask, next_remaining)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_mask, next_remaining))
        return {"arrival": None}
    return solve


